#ifndef NV_LIGHT_GPU_H
#define NV_LIGHT_GPU_H
#include <limits.h>
/* Bytecode generated by scripts/build_light_gpu_shaders.ps1. No runtime compile. */
#include "nv2a_light_cube_bytecode.h"
#include "nv2a_light_volume_bytecode.h"
typedef struct NvLightGPU {
 ID3D11ComputeShader *cube,*volume;
 ID3D11Buffer *input,*params;
 ID3D11ShaderResourceView *source;
 unsigned failed;
} NvLightGPU;
static void nv_light_gpu_shutdown(NvLightGPU*g){
 if(g->cube)ID3D11ComputeShader_Release(g->cube);
 if(g->volume)ID3D11ComputeShader_Release(g->volume);
 if(g->source)ID3D11ShaderResourceView_Release(g->source);
 if(g->input)ID3D11Buffer_Release(g->input);
 if(g->params)ID3D11Buffer_Release(g->params);
 memset(g,0,sizeof(*g));
}
static int nv_light_gpu_init(NvLightGPU*g,ID3D11Device*d){
 if(g->source)return 1;if(g->failed)return 0;
 if(FAILED(ID3D11Device_CreateComputeShader(d,nv_light_cube_code,sizeof(nv_light_cube_code),NULL,&g->cube))||
    FAILED(ID3D11Device_CreateComputeShader(d,nv_light_volume_code,sizeof(nv_light_volume_code),NULL,&g->volume)))goto fail;
 D3D11_BUFFER_DESC bd={0};bd.ByteWidth=2*1024*1024;bd.Usage=D3D11_USAGE_DYNAMIC;
 bd.BindFlags=D3D11_BIND_SHADER_RESOURCE;bd.CPUAccessFlags=D3D11_CPU_ACCESS_WRITE;
 if(FAILED(ID3D11Device_CreateBuffer(d,&bd,NULL,&g->input)))goto fail;
 D3D11_SHADER_RESOURCE_VIEW_DESC sd={0};sd.Format=DXGI_FORMAT_R32_UINT;sd.ViewDimension=D3D11_SRV_DIMENSION_BUFFER;sd.Buffer.NumElements=bd.ByteWidth/4;
 if(FAILED(ID3D11Device_CreateShaderResourceView(d,(ID3D11Resource*)g->input,&sd,&g->source)))goto fail;
 bd.ByteWidth=16;bd.BindFlags=D3D11_BIND_CONSTANT_BUFFER;
 if(FAILED(ID3D11Device_CreateBuffer(d,&bd,NULL,&g->params)))goto fail;
 return 1;
fail:nv_light_gpu_shutdown(g);g->failed=1;return 0;
}
/* Called only after source-range validation; owns no guest pointers. Results
 * are immediately consumed by later GPU draws on this same immediate context.
 * Nothing is mapped for read, flushed or waited on. Failed setup is CPU fallback. */
static int nv_light_gpu_convert(NvLightGPU*g,ID3D11Device*d,const uint8_t*bytes,size_t size,
 unsigned w,unsigned h,unsigned depth,unsigned cube,unsigned signs,
 ID3D11Resource**resource,ID3D11ShaderResourceView**view){
 *resource=NULL;*view=NULL;
 if(!size||size>2*1024*1024||!nv_light_gpu_init(g,d))return 0;
 ID3D11DeviceContext*c=NULL;ID3D11Device_GetImmediateContext(d,&c);
 ID3D11Resource*r=NULL;ID3D11ShaderResourceView*v=NULL;ID3D11UnorderedAccessView*u=NULL;
 D3D11_MAPPED_SUBRESOURCE map;HRESULT hr=E_FAIL;
 DXGI_FORMAT format=signs?DXGI_FORMAT_R32G32B32A32_FLOAT:DXGI_FORMAT_R8G8B8A8_UNORM;
 if(cube){
  D3D11_TEXTURE2D_DESC td={0};td.Width=w;td.Height=h;td.MipLevels=1;td.ArraySize=6;td.Format=format;td.SampleDesc.Count=1;
  td.BindFlags=D3D11_BIND_SHADER_RESOURCE|D3D11_BIND_UNORDERED_ACCESS;td.MiscFlags=D3D11_RESOURCE_MISC_TEXTURECUBE;
  ID3D11Texture2D*t=NULL;hr=ID3D11Device_CreateTexture2D(d,&td,NULL,&t);r=(ID3D11Resource*)t;
 }else{
  D3D11_TEXTURE3D_DESC td={0};td.Width=w;td.Height=h;td.Depth=depth;td.MipLevels=1;td.Format=format;
  td.BindFlags=D3D11_BIND_SHADER_RESOURCE|D3D11_BIND_UNORDERED_ACCESS;
  ID3D11Texture3D*t=NULL;hr=ID3D11Device_CreateTexture3D(d,&td,NULL,&t);r=(ID3D11Resource*)t;
 }
 if(FAILED(hr))goto done;
 D3D11_SHADER_RESOURCE_VIEW_DESC sd={0};sd.Format=format;
 sd.ViewDimension=cube?D3D11_SRV_DIMENSION_TEXTURECUBE:D3D11_SRV_DIMENSION_TEXTURE3D;
 if(cube)sd.TextureCube.MipLevels=1;else sd.Texture3D.MipLevels=1;
 if(FAILED(ID3D11Device_CreateShaderResourceView(d,r,&sd,&v))||
    FAILED(ID3D11Device_CreateUnorderedAccessView(d,r,NULL,&u)))goto done;
 if(FAILED(ID3D11DeviceContext_Map(c,(ID3D11Resource*)g->input,0,D3D11_MAP_WRITE_DISCARD,0,&map)))goto done;
 memcpy(map.pData,bytes,size);memset((uint8_t*)map.pData+size,0,((size+3)&~(size_t)3)-size);
 ID3D11DeviceContext_Unmap(c,(ID3D11Resource*)g->input,0);
 if(FAILED(ID3D11DeviceContext_Map(c,(ID3D11Resource*)g->params,0,D3D11_MAP_WRITE_DISCARD,0,&map)))goto done;
 uint32_t params[4]={w,h,depth,signs};memcpy(map.pData,params,16);ID3D11DeviceContext_Unmap(c,(ID3D11Resource*)g->params,0);
 /* Preserve the occupied compute slots, including dynamic shader linkage. */
 ID3D11ComputeShader*old_shader=NULL;ID3D11ClassInstance*instances[256]={0};UINT instance_count=256;
 ID3D11ShaderResourceView*old_source=NULL;ID3D11UnorderedAccessView*old_uav=NULL;ID3D11Buffer*old_params=NULL;
 ID3D11DeviceContext_CSGetShader(c,&old_shader,instances,&instance_count);
 ID3D11DeviceContext_CSGetShaderResources(c,0,1,&old_source);
 ID3D11DeviceContext_CSGetUnorderedAccessViews(c,0,1,&old_uav);
 ID3D11DeviceContext_CSGetConstantBuffers(c,0,1,&old_params);
 ID3D11DeviceContext_CSSetShader(c,cube?g->cube:g->volume,NULL,0);
 ID3D11DeviceContext_CSSetShaderResources(c,0,1,&g->source);
 ID3D11DeviceContext_CSSetConstantBuffers(c,0,1,&g->params);
 UINT keep=UINT_MAX;ID3D11DeviceContext_CSSetUnorderedAccessViews(c,0,1,&u,&keep);
 ID3D11DeviceContext_Dispatch(c,(w+7)/8,(h+7)/8,cube?6:depth);
 ID3D11UnorderedAccessView*none=NULL;ID3D11DeviceContext_CSSetUnorderedAccessViews(c,0,1,&none,&keep);
 ID3D11DeviceContext_CSSetShaderResources(c,0,1,&old_source);
 ID3D11DeviceContext_CSSetConstantBuffers(c,0,1,&old_params);
 ID3D11DeviceContext_CSSetUnorderedAccessViews(c,0,1,&old_uav,&keep);
 ID3D11DeviceContext_CSSetShader(c,old_shader,instances,instance_count);
 if(old_shader)ID3D11ComputeShader_Release(old_shader);
 if(old_source)ID3D11ShaderResourceView_Release(old_source);
 if(old_params)ID3D11Buffer_Release(old_params);
 if(old_uav)ID3D11UnorderedAccessView_Release(old_uav);
 for(UINT i=0;i<instance_count;i++)ID3D11ClassInstance_Release(instances[i]);
 *resource=r;*view=v;r=NULL;v=NULL;hr=S_OK;
done:
 if(u)ID3D11UnorderedAccessView_Release(u);if(v)ID3D11ShaderResourceView_Release(v);
 if(r)ID3D11Resource_Release(r);ID3D11DeviceContext_Release(c);
 return SUCCEEDED(hr)&&*resource&&*view;
}
#endif
